import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 5000010;
    static final int INFINITY = 1000000000;
    static int n, m, k, v1, v2, s, t;
    static int[] dist = new int[MAXN];
    static boolean[] visited = new boolean[MAXN];

    static class Edge {
        int to, next, v, cost;
        Edge(int to, int next, int v, int cost) {
            this.to = to;
            this.next = next;
            this.v = v;
            this.cost = cost;
        }
    }

    static Edge[] graph = new Edge[MAXN];
    static int[] head = new int[MAXN];
    static int cnt = 1;

    static int P(int x, int k) {
        return x + (k - 1) * n;
    }

    static void connect(int from, int to, int val, int cost) {
        graph[++cnt] = new Edge(to, head[from], val, cost);
        head[from] = cnt;
        graph[++cnt] = new Edge(from, head[to], 0, -cost);
        head[to] = cnt;
    }

    static boolean bell() {
        Queue<Integer> q = new LinkedList<>();
        for (int i = s; i <= t; ++i) {
            dist[i] = INFINITY;
            visited[i] = false;
        }
        q.offer(s);
        dist[s] = 0;
        visited[s] = true;
        while (!q.isEmpty()) {
            int x = q.poll();
            visited[x] = false;
            for (int i = head[x]; i != 0; i = graph[i].next) {
                int y = graph[i].to, c = graph[i].cost;
                if (dist[y] <= dist[x] + c || graph[i].v == 0) continue;
                dist[y] = dist[x] + c;
                if (!visited[y]) {
                    visited[y] = true;
                    q.offer(y);
                }
            }
        }
        return dist[t] != INFINITY;
    }

    static int augment(int x, int flow_limit) {
        if (x == t) return flow_limit;
        visited[x] = true;
        int res = flow_limit;
        for (int i = head[x]; i != 0; i = graph[i].next) {
            int y = graph[i].to, v = graph[i].v;
            if (dist[y] != dist[x] + graph[i].cost || v == 0 || visited[y]) continue;
            int f = augment(y, Math.min(res, v));
            if (f > 0) {
                res -= f;
                graph[i].v -= f;
                graph[i ^ 1].v += f;
                if (res == 0) break;
            }
        }
        return flow_limit - res;
    }

    static int minCostFlow() {
        int total = 0, flow;
        while (bell()) {
            while ((flow = augment(s, INFINITY)) > 0) {
                total += flow * dist[t];
            }
        }
        return total;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        k = Integer.parseInt(st.nextToken());
        v1 = Integer.parseInt(st.nextToken());
        v2 = Integer.parseInt(st.nextToken());

        s = 0;
        t = P(n, 110) + 1;

        for (int i = 2; i <= 110; ++i) {
            connect(P(1, i), t, INFINITY, 0);
        }

        for (int i = 2; i <= n; ++i) {
            for (int j = 1; j < 110; ++j) {
                connect(P(i, j), P(i, j + 1), INFINITY, v1);
            }
        }

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < k; ++i) {
            int x = Integer.parseInt(st.nextToken());
            connect(s, P(x, 1), 1, 0);
        }

        for (int i = 0; i < m; ++i) {
            st = new StringTokenizer(br.readLine());
            int x = Integer.parseInt(st.nextToken());
            int y = Integer.parseInt(st.nextToken());
            for (int j = 1; j < 110; ++j) {
                connect(P(x, j), P(y, j + 1), 1, v2 * (2 * l - 1) + v1);
                connect(P(y, j), P(x, j + 1), 1, v2 * (2 * l - 1) + v1);
            }
        }

        System.out.println(minCostFlow());
    }
}
